-- Mock private financials database for the company-profile skill.
-- ALL FIGURES AND PEOPLE ARE FICTIONAL (EUR thousands unless noted).
-- Entries with real company names (ids 1-3) carry mock financials for pipeline testing
-- and intentionally have NO shareholders/management rows - research those online.
-- Fully fictional entries (id 4 'Nortec Automation' and ids 5-100) are self-contained
-- demo entities: description, portfolio, shareholders and management included.
CREATE TABLE companies (
  id INTEGER PRIMARY KEY, name TEXT, nif TEXT, country TEXT, website TEXT, sector TEXT, city TEXT,
  description TEXT, portfolio TEXT
);
CREATE TABLE shareholders (company_id INTEGER REFERENCES companies(id), name TEXT, pct TEXT);
CREATE TABLE management (company_id INTEGER REFERENCES companies(id), name TEXT, role TEXT);
CREATE TABLE financials (
  company_id INTEGER REFERENCES companies(id), year INTEGER,
  revenue REAL, revenue_growth_pct REAL, cogs REAL, gross_margin REAL, gross_margin_pct REAL,
  external_services REAL, personnel_costs REAL, other_gains_losses REAL,
  ebitda REAL, ebitda_margin_pct REAL, exports REAL, exports_pct_revenue REAL,
  employees INTEGER, fixed_assets REAL, inventories REAL,
  net_financial_debt REAL, nfd_ebitda REAL, equity REAL
);
